use verus::prelude::*;

#[requires(x.len() > 0)]
#[ensures(result < x.len())]
#[ensures(forall(|j: usize| j < x.len() ==> x[result] >= x[j]))]
fn myfun1(x: &Vec<i32>) -> usize {
    // We require at the spec‐level that the vector be non‐empty.
    // We also re‐check it at run time.
    assert!(x.len() > 0, "Input vector must be non‐empty");

    let mut max_index = 0;
    let mut max_value = x[0];

    // Loop invariants to show that at each iteration i:
    //   1) max_index < i,
    //   2) i <= x.len(),
    //   3) for all k < i, x[max_index] >= x[k].
    // We also decrease the quantity x.len() - i to ensure termination.
    #[invariant(max_index < i)]
    #[invariant(i <= x.len())]
    #[invariant(forall(|k: usize| k < i ==> x[max_index] >= x[k]))]
    #[decreases(x.len() - i)]
    for (i, &v) in x.iter().enumerate().skip(1) {
        if v > max_value {
            max_value = v;
            max_index = i;
        }
    }

    max_index
}

